// painel in the browser: the same panels, prompt and keys as the terminal app
// (github.com/thiagokimo/nix-painel), from the same config. config.js holds the
// entries and projects.js the project folders, both generated by Nix.
//
// Tools, scripts and projects run in kitty through launch: links, which
// startpage-launch handles; links open in this tab.
(() => {
  const cfg = window.PAINEL;
  const projects = window.PAINEL_PROJECTS || [];
  const $ = (id) => document.getElementById(id);
  const KINDS = ["tool", "script", "project", "link"];
  const TITLES = { tool: "tools", script: "scripts", project: "projects", link: "links" };

  // ---- items -------------------------------------------------------------

  const items = [
    ...cfg.tools.map((t) => ({ ...t, kind: "tool", url: `launch:tool/${t.name}` })),
    ...cfg.scripts.map((t) => ({ ...t, kind: "script", url: `launch:script/${t.name}` })),
    ...projects.map((p) => ({ name: p.name, alias: "", branch: p.branch, desc: p.branch ? ` ${p.branch}` : "", kind: "project" })),
    ...cfg.links.flatMap((g) => g.links.map((l) => ({ ...l, desc: "", kind: "link", group: g.name }))),
  ];
  const openers = cfg.openWith.map((o) => ({ ...o, key: o.key || o.name[0].toLowerCase() }));

  const panels = KINDS.map((kind) => ({
    kind,
    box: document.querySelector(`.box[data-kind="${kind}"]`),
    items: items.flatMap((it, i) => (it.kind === kind ? [i] : [])),
    cursor: 0,
  })).filter((p) => {
    p.box.hidden = p.items.length === 0;
    return p.items.length > 0;
  });

  // ---- state, as in painel's Model -----------------------------------------

  const state = {
    mode: "prompt", // or "normal"
    focus: 0,
    matches: [],
    sel: 0,
    choosing: null, // the project being asked about
    choice: 0,
    status: "",
    statusErr: false,
  };
  const input = $("input");

  // ---- matching: alias, then name, then fuzzy, like painel -----------------

  // A subsequence match scored like a fuzzy finder: runs of letters and
  // matches at word starts score higher, gaps cost a little.
  const fuzzy = (q, name) => {
    const n = name.toLowerCase();
    let score = 0;
    let last = -2;
    let j = 0;
    for (let i = 0; i < n.length && j < q.length; i++) {
      if (n[i] !== q[j]) continue;
      score += 1;
      if (i === last + 1) score += 5;
      if (i === 0 || "-_. /".includes(n[i - 1])) score += 8;
      if (last >= 0) score -= Math.min(i - last - 1, 3);
      last = i;
      j++;
    }
    return j === q.length ? score : null;
  };

  const match = (text) => {
    const q = text.trim().toLowerCase();
    if (!q) return [];
    const out = [];
    const add = (i) => out.includes(i) || out.push(i);
    items.forEach((it, i) => it.alias && it.alias.toLowerCase() === q && add(i));
    items.forEach((it, i) => it.name.toLowerCase() === q && add(i));
    items
      .map((it, i) => ({ i, s: fuzzy(q, it.name) }))
      .filter((m) => m.s !== null)
      .sort((a, b) => b.s - a.s || items[a.i].name.length - items[b.i].name.length)
      .forEach((m) => add(m.i));
    return out;
  };

  const looksLikeUrl = (q) => /^[a-z][a-z0-9+.-]*:\/\//i.test(q) || /^[\w-]+(\.[\w-]+)+(:\d+)?(\/\S*)?$/.test(q);

  // ---- running -----------------------------------------------------------

  const setStatus = (text, err = false) => {
    state.status = text;
    state.statusErr = err;
  };

  const launch = (url, what) => {
    window.location.href = url;
    setStatus(`launched ${what}`);
  };

  const activate = (i) => {
    const it = items[i];
    if (it.kind === "link") {
      window.location.href = it.url;
    } else if (it.kind === "project") {
      if (openers.length === 1) {
        launch(`launch:project/${it.name}/${openers[0].name}`, `${it.name} in ${openers[0].name}`);
      } else {
        state.choosing = it;
        state.choice = 0;
      }
    } else {
      launch(it.url, it.name);
    }
  };

  const choose = () => {
    const it = state.choosing;
    const o = openers[state.choice];
    state.choosing = null;
    launch(`launch:project/${it.name}/${o.name}`, `${it.name} in ${o.name}`);
  };

  const submit = () => {
    const q = input.value.trim();
    if (!q) return;
    const [first] = state.matches.length ? [state.matches[state.sel]] : [];
    input.value = "";
    refilter();
    if (first !== undefined) activate(first);
    else if (looksLikeUrl(q)) window.location.href = /^[a-z][a-z0-9+.-]*:\/\//i.test(q) ? q : `https://${q}`;
    else if (cfg.search) window.location.href = cfg.search + encodeURIComponent(q);
    else setStatus(`nothing matches ${q}`, true);
  };

  const refilter = () => {
    state.matches = match(input.value);
    state.sel = 0;
  };

  // ---- drawing -----------------------------------------------------------

  const el = (tag, cls, text) => {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  };

  const row = (i, selected) => {
    const it = items[i];
    const a = el("a", "row" + (selected ? " sel" : ""));
    a.href = it.kind === "project" ? "#" : it.url;
    a.dataset.item = i;
    a.append(el("span", "mark", selected ? "❯ " : "  "));
    if (it.alias) a.append(el("span", "alias", `[${it.alias}] `));
    a.append(el("span", "name", it.name));
    if (it.desc) a.append(el("span", "desc", `  ${it.desc}`));
    return a;
  };

  const draw = () => {
    const filtering = input.value.trim() !== "";
    let selected = -1;
    if (filtering && state.matches.length) selected = state.matches[state.sel];
    else if (!filtering && state.mode === "normal") {
      const p = panels[state.focus];
      selected = p.items[p.cursor];
    }

    panels.forEach((p, n) => {
      p.box.classList.toggle("focused", state.mode === "normal" && n === state.focus);
      const title = el("h2");
      title.append(TITLES[p.kind], el("span", "count", ` ${p.items.length}`));
      const rows = el("div", "rows");
      const order = filtering ? state.matches.filter((i) => items[i].kind === p.kind) : p.items;
      let group = "";
      for (const i of order) {
        const it = items[i];
        if (it.kind === "link" && it.group !== group) {
          group = it.group;
          rows.append(el("div", "group", group));
        }
        rows.append(row(i, i === selected));
      }
      if (!order.length) rows.append(el("div", "empty", "no matches"));
      p.box.replaceChildren(title, rows);
      rows.querySelector(".sel")?.scrollIntoView({ block: "nearest" });
    });

    document.body.classList.toggle("normal", state.mode === "normal");
    $("backdrop").hidden = state.choosing === null;
    if (state.choosing) drawDialog();

    const hint = $("hint");
    hint.className = "hint" + (state.status ? (state.statusErr ? " err" : " ok") : "");
    if (state.status) {
      hint.textContent = state.status;
    } else if (state.mode === "prompt") {
      hint.textContent = "enter run · ↑↓ pick · tab complete · esc navigate";
    } else {
      hint.textContent = "hjkl move · enter run · y yazi here · / search";
    }
  };

  // A dialog like painel's: a box over the dimmed page, the title and branch
  // on its top edge, one row per way to open the project, the keys on its
  // bottom edge.
  const drawDialog = () => {
    const it = state.choosing;
    const title = el("h2");
    title.append("open ", el("span", "project", it.name));
    const parts = [title];
    if (it.branch) parts.push(el("span", "summary", `\ue0a0 ${it.branch}`));
    const rows = el("div", "rows");
    const label = (o) => `[${o.key}] ${o.name}`;
    const width = Math.max(...openers.map((o) => label(o).length));
    openers.forEach((o, n) => {
      const picked = n === state.choice;
      const r = el("div", "row opt" + (picked ? " sel" : ""));
      r.dataset.choice = n;
      r.append(
        el("span", "mark", picked ? "❯ " : "  "),
        el("span", "alias", `[${o.key}] `),
        el("span", "name", o.name),
        el("span", "desc", " ".repeat(width - label(o).length) + "   " + o.cmd),
      );
      rows.append(r);
    });
    parts.push(rows, el("span", "keys", `${openers.map((o) => o.key).join("/")} pick · ↑↓ move · enter open · esc cancel`));
    $("dialog").replaceChildren(...parts);
  };

  // ---- keys ----------------------------------------------------------------

  const toPrompt = () => {
    state.mode = "prompt";
    input.focus();
  };

  const toNormal = () => {
    state.mode = "normal";
    input.blur();
  };

  const chooseKey = (ev) => {
    const k = ev.key;
    const byKey = openers.findIndex((o) => o.key === k);
    if (byKey >= 0) {
      state.choice = byKey;
      choose();
    } else if (k === "Escape" || k === "q") {
      state.choosing = null;
    } else if (k === "Enter") {
      choose();
    } else if (["ArrowLeft", "ArrowUp", "h", "k"].includes(k) || (k === "Tab" && ev.shiftKey)) {
      state.choice = (state.choice + openers.length - 1) % openers.length;
    } else if (["ArrowRight", "ArrowDown", "l", "j", "Tab"].includes(k)) {
      state.choice = (state.choice + 1) % openers.length;
    } else {
      return false;
    }
    return true;
  };

  const promptKey = (ev) => {
    const ctrl = ev.ctrlKey;
    switch (true) {
      case ev.key === "Escape":
        if (input.value) {
          input.value = "";
          refilter();
        } else toNormal();
        return true;
      case ev.key === "Enter":
        submit();
        return true;
      case ev.key === "ArrowUp" || (ctrl && (ev.key === "p" || ev.key === "k")):
        state.sel = Math.max(state.sel - 1, 0);
        return true;
      case ev.key === "ArrowDown" || (ctrl && (ev.key === "n" || ev.key === "j")):
        state.sel = Math.min(state.sel + 1, Math.max(state.matches.length - 1, 0));
        return true;
      case ev.key === "Tab":
        if (state.matches.length) {
          input.value = items[state.matches[state.sel]].name;
          refilter();
        }
        return true;
    }
    return false;
  };

  const normalKey = (ev) => {
    const p = panels[state.focus];
    if (!p) return false;
    const k = ev.key;
    if (["/", "i", ":"].includes(k)) toPrompt();
    else if (k === "j" || k === "ArrowDown") p.cursor = Math.min(p.cursor + 1, p.items.length - 1);
    else if (k === "k" || k === "ArrowUp") p.cursor = Math.max(p.cursor - 1, 0);
    else if (k === "g" || k === "Home") p.cursor = 0;
    else if (k === "G" || k === "End") p.cursor = p.items.length - 1;
    else if (k === "l" || k === "ArrowRight" || (k === "Tab" && !ev.shiftKey)) state.focus = (state.focus + 1) % panels.length;
    else if (k === "h" || k === "ArrowLeft" || (k === "Tab" && ev.shiftKey)) state.focus = (state.focus + panels.length - 1) % panels.length;
    else if (k === "Enter") activate(p.items[p.cursor]);
    else if (k === "y" && p.kind === "project" && cfg.hasAlt) {
      const it = items[p.items[p.cursor]];
      launch(`launch:project/${it.name}/alt`, `${it.name} in ${cfg.altName}`);
    } else return false;
    return true;
  };

  document.addEventListener("keydown", (ev) => {
    if (ev.altKey || ev.metaKey || (ev.ctrlKey && !["p", "n", "j", "k"].includes(ev.key))) return;
    const hadStatus = state.status !== "";
    state.status = "";
    let handled;
    if (state.choosing) handled = chooseKey(ev);
    else if (state.mode === "prompt") handled = promptKey(ev);
    else handled = normalKey(ev);
    if (handled) {
      ev.preventDefault();
      draw();
    } else if (hadStatus) draw();
  });

  input.addEventListener("input", () => {
    refilter();
    draw();
  });

  // Clicking the prompt goes back to it; clicking a row runs it.
  input.addEventListener("focus", () => {
    if (state.mode !== "prompt") {
      state.mode = "prompt";
      draw();
    }
  });

  $("panels").addEventListener("click", (ev) => {
    const a = ev.target.closest("a.row");
    if (!a) return;
    const it = items[Number(a.dataset.item)];
    if (it.kind === "project" || it.url.startsWith("launch:")) {
      ev.preventDefault();
      activate(Number(a.dataset.item));
      draw();
    }
  });

  // In the dialog, a click on a row opens with it; outside it cancels.
  $("backdrop").addEventListener("click", (ev) => {
    const opt = ev.target.closest(".opt");
    if (opt) {
      state.choice = Number(opt.dataset.choice);
      choose();
    } else if (!ev.target.closest(".dialog")) {
      state.choosing = null;
    }
    draw();
  });

  // ---- header ------------------------------------------------------------

  $("user").textContent = `${cfg.user}@${cfg.host}`;
  document.title = `${cfg.user}@${cfg.host} ~ painel`;
  const tick = () => {
    const now = new Date();
    const day = now.toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" });
    const time = now.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
    $("clock").textContent = `${day.replace(",", "")} · ${time}`;
  };
  tick();
  setInterval(tick, 15_000);

  draw();
  input.focus();
})();
